from django.http import HttpResponse
from .views import home as base_home

# Optimized copies of the three bicycle-spare photos supplied for this change.
BIKE_1 = "data:image/webp;base64,"
BIKE_2 = "data:image/webp;base64,"
BIKE_3 = "data:image/webp;base64,"

CSS = f"""
.bike-slide .bike-feature-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;width:100%;height:100%}}
.bike-slide .bike-feature-grid img{{width:100%;height:100%;object-fit:cover;border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,.22);border:1px solid rgba(255,255,255,.18)}}
.bike-slide .showcase-image.bike-showcase{{height:255px;padding:8px;background:linear-gradient(135deg,rgba(0,0,0,.2),rgba(25,217,120,.14));}}
.bike-slide .showcase-image.bike-showcase img{{width:100%;height:100%;object-fit:cover;border-radius:12px;}}
.bike-badge{{position:absolute;right:10px;top:10px;padding:6px 9px;border-radius:999px;background:rgba(25,217,120,.95);color:#052313;font-size:8px;font-weight:1000;z-index:4}}
.bike-card-gallery{{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:4px;height:100%;padding:4px;background:#071b31}}
.bike-card-gallery img{{width:100%;height:100%;object-fit:cover;border-radius:7px;min-width:0}}
.bike-card-gallery img:first-child{{grid-row:1 / 3}}
.market-card.bike-enhanced{{background:#071b31}}
.market-card.bike-enhanced:after{{background:linear-gradient(180deg,rgba(4,18,30,.02) 12%,rgba(4,18,30,.82) 100%)}}
.quick-card.bike-quick{{background:linear-gradient(135deg,#071b31,#0b4c38);color:#fff;border-color:rgba(25,217,120,.22)}}
.quick-card.bike-quick small{{color:#b9d5c8}}
@media(max-width:760px){{.bike-slide .bike-feature-grid{{height:190px}}}}
"""


def _bike_markup():
    return f"""
<div class="slide bike-slide" data-index="999">
  <img class="slide-photo" src="{BIKE_1}" alt="Bicycle spare parts" loading="lazy">
  <div class="hero-content">
    <div class="copy">
      <span class="eyebrow"><i class="live-dot"></i> BICYCLE SPARES · NEW ARRIVALS</span>
      <h1>Ride Strong.<br><span>Build Better.</span></h1>
      <p>Quality bicycle spares including cassette sprockets, hubs and freehub components for repairs, upgrades and custom builds.</p>
      <div class="actions"><a class="btn btn-white" href="/products/?q=bicycle">Shop bicycle spares →</a><a class="btn btn-outline" href="/products/?q=bicycle+spares">Browse all parts</a></div>
    </div>
    <div class="product-showcase">
      <div class="showcase-image bike-showcase">
        <div class="bike-feature-grid"><img src="{BIKE_1}" alt="Bicycle cassette sprocket"><img src="{BIKE_2}" alt="Bicycle freehub"><img src="{BIKE_3}" alt="Bicycle hubs"></div>
        <span class="bike-badge">⚙️ BIKE SPARES</span>
      </div>
      <div class="showcase-foot"><div><strong>Bicycle Spares</strong><small>Cassettes · Hubs · Freehubs</small><div class="showcase-price">Built for the next ride</div></div><a class="mini-cta" href="/products/?q=bicycle+spares">Shop now</a></div>
    </div>
  </div>
</div>
"""

JS = f"""
<script>
(function(){{
  const root=document.getElementById('shopiva-slider');
  if(!root || root.dataset.bikeEnhanced) return;
  root.dataset.bikeEnhanced='1';
  const controls=root.querySelector('.hero-controls');
  if(controls) controls.insertAdjacentHTML('beforebegin', `{_bike_markup().replace('`','\\`')}`);
  const dots=root.querySelector('.dots');
  if(dots){{
    const d=document.createElement('button');d.className='dot';d.dataset.slide=String(root.querySelectorAll('.slide').length-1);d.type='button';d.setAttribute('aria-label','Bicycle spares slide');dots.appendChild(d);
  }}
  const bikeCard=document.querySelector('.market-card[href*="q=bicycle"]');
  if(bikeCard){{
    bikeCard.classList.add('bike-enhanced');
    const old=bikeCard.querySelector('img');
    if(old){{
      const gallery=document.createElement('div');gallery.className='bike-card-gallery';
      gallery.innerHTML=`<img src="{BIKE_1}" alt="Bicycle cassette sprocket"><img src="{BIKE_2}" alt="Bicycle freehub"><img src="{BIKE_3}" alt="Bicycle hubs">`;
      old.replaceWith(gallery);
    }}
    const h=bikeCard.querySelector('h3');if(h)h.textContent='Bicycle Spares';
    const p=bikeCard.querySelector('p');if(p)p.textContent='Cassettes, hubs, freehubs and cycling components for repairs and upgrades.';
    const badge=bikeCard.querySelector('.market-badge');if(badge)badge.textContent='CYCLE SPARES';
  }}
  const quickGrid=document.querySelector('.quickgrid');
  if(quickGrid && !quickGrid.querySelector('.bike-quick')){{
    const a=document.createElement('a');a.className='quick-card bike-quick';a.href='/products/?q=bicycle+spares';a.innerHTML=`<span class="quick-icon" style="background-image:url('{BIKE_3}')"></span><span><b>Bicycle Spares</b><small>Cassettes · Hubs · Freehubs</small></span>`;quickGrid.appendChild(a);
  }}
}})();
</script>
"""


def enhanced_home(request):
    response = base_home(request)
    if getattr(response, "status_code", 200) != 200 or "text/html" not in response.get("Content-Type", "text/html"):
        return response
    html = response.content.decode(response.charset or "utf-8")
    marker = '<script>\n(function(){const root=document.getElementById(\'shopiva-slider\');'
    if marker not in html:
        marker = "<script>\n(function(){const root=document.getElementById('shopiva-slider');"
    injection = f"<style>{CSS}</style>\n{JS}"
    if marker in html:
        html = html.replace(marker, injection + "\n" + marker, 1)
    else:
        html = html.replace('</body>', injection + '\n</body>', 1)
    return HttpResponse(html, status=response.status_code, content_type=response.get("Content-Type", "text/html"))
